export type PerpetoTokens = typeof tokens;
export type ColorName = keyof typeof tokens.color | keyof typeof tokens.derivedColor;
export type CssVariable = keyof typeof tokens.cssVariables;

export const color = { ...tokens.color, ...tokens.derivedColor } as const;
export const cssVariables = tokens.cssVariables;

/** `var(--name)` reference for a generated custom property. */
export const cssVar = (name: CssVariable): string => `var(${name})`;

/** Pixel value for a 4px spacing step, e.g. space(4) === 16. */
export const space = (step: number): number => tokens.space.unit * step;
